server_scripts.script:
if "payments" in (frappe.get_hooks("app_name") or []):
    doctype = doc.get("doctype")
    closing = 0
    if doctype == "Sales Invoice" and doc.get("is_pos") and doc.get("is_consolidated"):
        refs = [row.get("pos_invoice") or "" for row in doc.get("items") or []]
        if refs and "" not in refs:
            logs = frappe.get_all(
                "POS Invoice Merge Log",
                filters={
                    "docstatus": 1,
                    "customer": doc.get("customer"),
                    "consolidated_invoice": ["is", "not set"],
                    "consolidated_credit_note": ["is", "not set"],
                },
                pluck="name",
            )
            for log in logs:
                covered = frappe.get_all(
                    "POS Invoice Reference",
                    filters={
                        "parenttype": "POS Invoice Merge Log",
                        "parent": log,
                        "pos_invoice": ["in", refs],
                    },
                    pluck="pos_invoice",
                )
                if not [ref for ref in refs if ref not in covered]:
                    closing = 1
    if doctype == "POS Invoice" or (
        doctype == "Sales Invoice"
        and doc.get("is_pos")
        and not closing
    ):
        payments = doc.get("payments") or []
        if payments:
            open_rows = frappe.get_all(
                "Payment Request",
                filters={
                    "reference_doctype": doctype,
                    "reference_name": doc.get("name"),
                    "status": ["in", ["Requested", "Initiated"]],
                },
                fields=["name", "payment_request_type"],
                order_by="name asc",
            )
            for open_row in open_rows:
                open_name = open_row.get("name")
                if open_row.get("payment_request_type") != "Outward":
                    frappe.throw(
                        "PAY-010: A phone payment for this bill is still open (Payment Request "
                        + open_name
                        + "). Wait for the guest to finish, or cancel that request first."
                    )
        used = []
        places = None
        # Each row is matched on its own. An earlier row can take requests a
        # later row needed. That fails closed; two rows on one gateway is unusual.
        for row in payments:
            amount = frappe.utils.flt(row.get("amount"))
            account = row.get("account")
            gateways = []
            if amount > 0 and account:
                gateways = frappe.get_all(
                    "Payment Gateway Account",
                    filters={"payment_account": account},
                    pluck="name",
                )
            if gateways:
                requests = frappe.get_all(
                    "Payment Request",
                    filters={
                        "reference_doctype": doctype,
                        "reference_name": doc.get("name"),
                        "status": "Paid",
                        "payment_gateway_account": ["in", gateways],
                    },
                    fields=["name", "grand_total", "mode_of_payment"],
                    order_by="name asc",
                )
                eligible = []
                for request in requests:
                    if (
                        request.get("name") not in used
                        and request.get("mode_of_payment") in (None, "", row.get("mode_of_payment"))
                    ):
                        eligible.append(request)
                if len(eligible) > 8:
                    frappe.throw(
                        "PAY-009: This bill has too many separate phone payments to match automatically. Ask a manager to settle it."
                    )
                if places is None:
                    places = doc.precision("grand_total")
                amount = frappe.utils.flt(row.get("amount"), places)
                picked = []
                for request in eligible:
                    if frappe.utils.flt(request.get("grand_total"), places) == amount:
                        picked.append(request.get("name"))
                        break
                if not picked:
                    count = len(eligible)
                    limit = 1
                    power = 0
                    while power < count:
                        limit = limit * 2
                        power = power + 1
                    mask = 1
                    while mask < limit and not picked:
                        total = 0
                        names = []
                        index = 0
                        bit = 1
                        while index < count:
                            if mask & bit:
                                total = frappe.utils.flt(
                                    total
                                    + frappe.utils.flt(
                                        eligible[index].get("grand_total"), places
                                    ),
                                    places,
                                )
                                names.append(eligible[index].get("name"))
                            bit = bit * 2
                            index = index + 1
                        if len(names) > 1 and total == amount:
                            picked = names
                        mask = mask + 1
                if not picked:
                    frappe.throw(
                        "PAY-007: This gateway payment needs a paid "
                        "Payment Request for the same amount."
                    )
                for picked_name in picked:
                    used.append(picked_name)
        if payments:
            paid_rows = frappe.get_all(
                "Payment Request",
                filters={
                    "reference_doctype": doctype,
                    "reference_name": doc.get("name"),
                    "status": ["in", ["Paid", "Partially Paid"]],
                },
                fields=["name", "payment_request_type"],
                order_by="name asc",
            )
            for paid_row in paid_rows:
                paid_name = paid_row.get("name")
                if paid_row.get("payment_request_type") != "Outward" and paid_name not in used:
                    frappe.throw(
                        "PAY-008: This bill was already paid by phone (Payment Request "
                        + paid_name
                        + "). Choose that phone payment to settle it, not cash or another method."
                    )

